// PMS → CRS: "Read the request"                        (workflow: PMS ID photos · Drive)
// Mode: Run Once for All Items.
//
// The PMS keeps a guest's ID photo in Google Drive, ENCRYPTED (D27-209). What
// arrives here is already a password-protected zip: this workflow never sees
// a photo or the password. It is asked three things: store a file, fetch one
// back, delete one.
//
// ── THE OWNER'S SETTINGS: edit these, nothing below them ────────────────────
// Each PMS hotel code → the id of ITS folder inside "ID photos" in Drive.
// Open the folder in Drive: the id is the last part of its address, after
// /folders/. A hotel with no folder id here is refused.
const HOTELS = {
  "5EL": "",
  "AMR": "",
  "GLM": "",
};
// ─────────────────────────────────────────────────────────────────────────────

const m = $input.first().json.body ?? {};
const stop = (statusCode, error) => [{ json: { stop: true, statusCode, answer: { ok: false, error } } }];

const folderId = HOTELS[m.hotel];
if (!folderId) return stop(422, `Hotel ${m.hotel ?? "-"} has no folder in this workflow's HOTELS list.`);

if (m.action === "store") {
  // Named by the PMS's own record and nothing else: no guest, no booking.
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.zip$/.test(m.name ?? "")) {
    return stop(400, "Not a file name the PMS makes.");
  }
  if (typeof m.base64 !== "string" || m.base64.length < 100 || !/^[A-Za-z0-9+/]+=*$/.test(m.base64)) {
    return stop(400, "No file was sent.");
  }
  // ONLY AN ENCRYPTED ZIP IS STORED. A zip whose first file is AES-encrypted
  // says so in its first bytes (method 99, the encrypted flag): a plain photo,
  // or a plain zip, sent here by mistake is refused rather than kept readable.
  const head = Buffer.from(m.base64.slice(0, 16), "base64");
  if (head.length < 10 || head.readUInt32LE(0) !== 0x04034b50 || (head.readUInt16LE(6) & 1) !== 1 || head.readUInt16LE(8) !== 99) {
    return stop(400, "Only the PMS's encrypted bundles are stored here.");
  }
  return [{
    json: { stop: false, store: true, action: "store", folderId, name: m.name },
    binary: { data: { data: m.base64, mimeType: "application/zip", fileName: m.name } },
  }];
}

if (m.action === "fetch" || m.action === "delete") {
  if (!/^[A-Za-z0-9_-]{10,100}$/.test(m.fileId ?? "")) return stop(400, "Not a Drive file id.");
  const file = `https://www.googleapis.com/drive/v3/files/${m.fileId}`;
  return [{
    json: {
      stop: false, store: false, action: m.action, folderId, fileId: m.fileId,
      file, whereUrl: `${file}?fields=id,parents,trashed`,
    },
  }];
}

return stop(400, "The action is store, fetch or delete.");

// PMS → CRS: "Stored"
// Mode: Run Once for All Items.
//
// Input: the Drive node's answer. The PMS keeps the file's id, and nothing
// else tells it where the photo is.
const file = $input.first().json;
if (!file.id) return [{ json: { statusCode: 502, answer: { ok: false, error: "Drive gave no file id." } } }];
return [{ json: { statusCode: 200, answer: { ok: true, fileId: file.id } } }];

// PMS → CRS: "One of ours?"
// Mode: Run Once for All Items.
//
// Input: Drive's own record of the file (HTTP Request, Never Error on).
//
// ⚠ ONLY A FILE IN THIS HOTEL'S OWN FOLDER is fetched or deleted. The secret
// on this workflow's address must not be a way to read or remove anything
// else in the Drive.
function parse(body) {
  if (typeof body !== "string") return body ?? {};
  try { return JSON.parse(body); } catch { return {}; }
}

const req = $("Read the request").first().json;
const res = $input.first().json;
const answer = (statusCode, body) => [{ json: { stop: true, statusCode, answer: body } }];

if (res.statusCode === 404) {
  // Already gone is what a delete wants; a fetch has nothing to give.
  return req.action === "delete"
    ? answer(200, { ok: true, deleted: true })
    : answer(404, { ok: false, error: "No such file in Drive." });
}
if (res.statusCode !== 200) return answer(502, { ok: false, error: `Drive answered ${res.statusCode}.` });

const file = parse(res.body);
if (!Array.isArray(file.parents) || !file.parents.includes(req.folderId) || file.trashed === true) {
  return answer(403, { ok: false, error: "That file is not one of this hotel's ID photos." });
}
return [{ json: { ...req, fetch: req.action === "fetch" } }];

// PMS → CRS: "Fetched"
// Mode: Run Once for All Items.
//
// Input: the file, as binary "data" (HTTP Request, response format File).
// It goes back to the PMS as it was stored: still encrypted.
const bytes = await this.helpers.getBinaryDataBuffer(0, "data");
return [{ json: { statusCode: 200, answer: { ok: true, base64: bytes.toString("base64") } } }];

// PMS → CRS: "Deleted"
// Mode: Run Once for All Items.
//
// Input: Drive's answer to the delete (HTTP Request, Never Error on). 204 is
// done; 404 is already gone. Anything else is said, so the PMS writes down
// that the file is still there and a manager tries again.
const res = $input.first().json;
if (res.statusCode === 204 || res.statusCode === 200 || res.statusCode === 404) {
  return [{ json: { statusCode: 200, answer: { ok: true, deleted: true } } }];
}
return [{ json: { statusCode: 502, answer: { ok: false, error: `Drive answered ${res.statusCode} to the delete.` } } }];
